steps.script:
GameState.set_edition(11)
var U = GameState.state["units"]
var models = []
for i in range(5):
	models.append({"id": "m%d" % (i + 1), "wounds": 4, "current_wounds": 4, "base_mm": 40, "position": {"x": 800.0 + i * 45.0, "y": 200.0}, "alive": true, "status_effects": []})
var weapons = [
	{"name": "Balistus grenade launcher", "type": "Ranged", "range": "18", "attacks": "D6", "ballistic_skill": "2", "strength": "4", "ap": "-1", "damage": "1", "special_rules": "blast", "abilities": [{"id": "blast"}]},
	{"name": "Castellan axe \u2013 Ranged", "type": "Ranged", "range": "24", "attacks": "2", "ballistic_skill": "2", "strength": "4", "ap": "-1", "damage": "2", "special_rules": "assault", "abilities": [{"id": "assault"}]},
	{"name": "Castellan axe \u2013 Melee", "type": "Melee", "range": "Melee", "attacks": "4", "weapon_skill": "2", "strength": "9", "ap": "-1", "damage": "3"}
]
U.merge({"U_ALLARUS_LD": {"id": "U_ALLARUS_LD", "squad_id": "U_ALLARUS_LD", "owner": 1, "status": 2, "flags": {}, "meta": {"name": "Allarus Custodians", "keywords": ["ADEPTUS CUSTODES", "ALLARUS CUSTODIANS", "IMPERIUM", "INFANTRY", "TERMINATOR"], "stats": {"move": 5, "toughness": 7, "save": 2, "wounds": 4, "leadership": 6, "objective_control": 2, "invuln": 4}, "points": 275, "is_warlord": false, "enhancements": [], "wargear": ["5x Balistus grenade launcher", "5x Castellan axe"], "weapons": weapons, "abilities": []}, "models": models}, "U_LD_TARGET": {"id": "U_LD_TARGET", "squad_id": "U_LD_TARGET", "owner": 2, "status": 2, "flags": {}, "meta": {"name": "Stormboyz Target", "keywords": ["INFANTRY", "ORKS"], "stats": {"move": 12, "toughness": 5, "save": 5, "wounds": 1, "leadership": 7, "objective_control": 1}, "weapons": [], "abilities": []}, "models": [{"id": "e1", "alive": true, "position": {"x": 800.0, "y": 760.0}, "base_mm": 32, "wounds": 1, "current_wounds": 1, "status_effects": []}, {"id": "e2", "alive": true, "position": {"x": 840.0, "y": 760.0}, "base_mm": 32, "wounds": 1, "current_wounds": 1, "status_effects": []}]}}, true)
return U.has("U_ALLARUS_LD") and U.has("U_LD_TARGET")

var p = PhaseManager.get_current_phase_instance()
p.game_state_snapshot["units"]["U_ALLARUS_LD"] = GameState.state["units"]["U_ALLARUS_LD"]
p.game_state_snapshot["units"]["U_LD_TARGET"] = GameState.state["units"]["U_LD_TARGET"]
return p.game_state_snapshot["units"].has("U_ALLARUS_LD")

var a = GameState.state["units"]["U_ALLARUS_LD"]["models"][0]["position"]
var b = GameState.state["units"]["U_LD_TARGET"]["models"][0]["position"]
var d = Vector2(a.x, a.y).distance_to(Vector2(b.x, b.y))
var edge = Measurement.px_to_inches(d - Measurement.mm_to_px(20.0) - Measurement.mm_to_px(16.0))
return edge > 0.0 and edge < 18.0

var mw = RulesEngine.get_unit_weapons("U_ALLARUS_LD", GameState.state)
var t = 0
for mid in mw:
	t += mw[mid].size()
return "%d_models_%d_guns" % [mw.size(), t]

var sc = tree.root.get_node_or_null("Main").shooting_controller
var it = sc.weapon_tree.get_root().get_first_child()
var rows = []
while it != null:
	rows.append(str(it.get_metadata(0)))
	it = it.get_next()
rows.sort()
return ",".join(rows)

var sc = tree.root.get_node_or_null("Main").shooting_controller
var it = sc.weapon_tree.get_root().get_first_child()
var labels = []
while it != null:
	labels.append(it.get_text(0))
	it = it.get_next()
labels.sort()
return " | ".join(labels)

var sc = tree.root.get_node_or_null("Main").shooting_controller
var it = sc.weapon_tree.get_root().get_first_child()
while it != null:
	if str(it.get_metadata(0)) == "castellan_axe___ranged_ranged":
		it.select(0)
		return true
	it = it.get_next()
return false

var sc = tree.root.get_node_or_null("Main").shooting_controller
var n = 0
for a in sc.current_phase.pending_assignments:
	if str(a.get("weapon_id", "")) == "castellan_axe___ranged_ranged":
		n += a.get("model_ids", []).size()
return n
